 <div className="guide-question"><Badge>Planzo guide</Badge><h3 ref={heading} tabIndex={-1}>{labels[step]}</h3><p>{['Where will you start, and when can you personally travel? Your times can differ from your friends’ times inside the tentative dates.','What is the most you can spend on the entire trip, including return travel, stays, food, activities, fees and contingency?','What would you enjoy? These interests and named places will be shared with your group after confirmation.','What must be true for you to join? Include food needs, accessibility, places you must cover, or travel restrictions. The planner will prioritise these and tell you when one cannot fit. You decide whether to accept the disclosed exclusions.','What would you like, but could adjust? You can describe pace, preferred activities or other trade-offs.','Check every answer below. Nothing in this conversation is saved until you confirm.'][step]}</p></div>
 {error&&<p className="form-error" role="alert">{error}</p>}
 <fieldset className="auth-fields" disabled={Boolean(frozen)}>
 {step===0&&<><Field label="Starting city"><input value={b.origin} maxLength={80} autoComplete="off" onChange={e=>update('origin',e.target.value)}/></Field><Field label="Tentative date option"><select value={b.window_id} disabled={editingDate} onChange={e=>{const win=w.windows.find(x=>x.id===e.target.value)!;setB(x=>({...x,window_id:win.id,start:win.start,end:win.end}));setAck(false);}}>{w.windows.map(win=><option key={win.id} value={win.id}>{flowStamp(win.start)} → {flowStamp(win.end)} IST</option>)}</select></Field><DateTimeField label="My earliest departure" value={b.start} onChange={v=>update('start',v)} onEditingChange={open=>editDate('start',open)}/><DateTimeField label="My latest return" value={b.end} onChange={v=>update('end',v)} onEditingChange={open=>editDate('end',open)}/></>}
 {step===1&&<><Field label="Whole-trip ceiling (INR)"><input inputMode="decimal" type="number" min="1" step="0.01" value={budget} onChange={e=>{setBudget(e.target.value);setAck(false);}}/></Field><Field label="Personal travel and extra-time allowance (INR)"><input inputMode="decimal" type="number" min="1" step="0.01" value={reserve} onChange={e=>{setReserve(e.target.value);setAck(false);}}/></Field><p className="caption">Set aside return travel from your city and any time before or after the shared itinerary. This is included within your ceiling, not added to it.</p></>}
 {step===2&&<><div className="interest-choices" role="group" aria-label="Shareable interests">{FLOW_INTERESTS.map(x=><button type="button" key={x} aria-pressed={b.interests.includes(x)} onClick={()=>update('interests',b.interests.includes(x)?b.interests.filter(y=>y!==x):[...b.interests,x])}>{x}</button>)}</div><Field label="Shareable places to visit, one per line"><textarea value={placeText} rows={5} maxLength={485} onChange={e=>{setPlaceText(e.target.value);setAck(false);}}/></Field><p className="caption">Only enter places you are happy to share. Keep private reasons in the next questions.</p></>}
 {step===3&&<Field label="My must-have requirements"><textarea rows={6} value={b.hard} maxLength={1500} onChange={e=>update('hard',e.target.value)} placeholder="For example: non-vegetarian meals must be available. Enter None if you have no must-haves."/></Field>}
 {step===4&&<Field label="My flexible preferences"><textarea rows={6} value={b.soft} maxLength={1500} onChange={e=>update('soft',e.target.value)} placeholder="For example: a relaxed beach day would be nice. Enter None if there are no other preferences."/></Field>}
 </fieldset>
 {step===0&&<fieldset className="auth-fields" disabled={Boolean(frozen)}><div className="field-grid"><Field label="Outbound travel time (hours)"><input type="number" min="0" max="72" step="0.5" value={outbound} onChange={e=>{setOutbound(e.target.value);setAck(false);}}/></Field><Field label="Return travel time (hours)"><input type="number" min="0" max="72" step="0.5" value={returnHours} onChange={e=>{setReturnHours(e.target.value);setAck(false);}}/></Field></div><p className="caption">Include transfers and buffers. Use zero if you are already at the destination. These are your planning allowances; live schedules will be checked at booking.</p></fieldset>}
 {step===5&&<><dl className="personal-summary"><dt>Starting city</dt><dd>{b.origin}</dd><dt>My travel availability</dt><dd>{flowStamp(b.start)} → {flowStamp(b.end)} IST</dd><dt>Outbound / return travel time</dt><dd>{draft().outbound_minutes/60} hours / {draft().return_minutes/60} hours</dd><dt>Whole-trip ceiling</dt><dd>{flowMoney(draft().ceiling_paise)}</dd><dt>Personal travel and extra-time allowance</dt><dd>{flowMoney(draft().travel_reserve_paise)}</dd><dt>Shareable interests and places</dt><dd>{[...b.interests,...draft().places].join(' · ')||'A relaxed shared plan'}</dd><dt>Private must-haves</dt><dd className="preserve-lines">{b.hard}</dd><dt>Private flexible preferences</dt><dd className="preserve-lines">{b.soft}</dd></dl>
 <fieldset className="auth-fields" disabled={Boolean(frozen)}><h3>Planning requests to consider</h3><p>Check that every must-have and flexible wish you want planned appears here. Edit the short requests and their types. These exact requests will be shared with your group and, with consent, Gemini; private reasons above stay private.</p>
 <PlanningRequestsEditor value={requestDraft??suggestPlanningRequests(b.hard,b.soft)} onChange={v=>{setRequestDraft(v);setRequestsReviewed(false);setAck(false);}}/>
 {!saved?.confirmed&&<label className="check"><input type="checkbox" checked={requestsReviewed} onChange={e=>{setRequestsReviewed(e.target.checked);setAck(false);}}/>I reviewed every request to share above. I understand that a request may be excluded with a reason if it cannot fit.</label>}
 {saved?.confirmed&&!saved.content.requests_reviewed&&<p className="caption">This older summary did not share planning requests. Reopen it to review the requests before a new generation.</p>}
 </fieldset>
 {!saved?.confirmed&&!['archived','postponed'].includes(state.stage)&&<fieldset className="auth-fields" disabled={busy}>
 {w.trip.name.startsWith('TEST · AI')&&<><label className="check"><input type="checkbox" checked={b.fictional} onChange={e=>{update('fictional',e.target.checked);if(!e.target.checked)update('ai_consent',false);}}/>These answers are fictional test inputs.</label><label className="check"><input type="checkbox" checked={b.ai_consent} disabled={!b.fictional} onChange={e=>update('ai_consent',e.target.checked)}/>Allow Gemini</label><p className="caption">Only the reviewed, shareable fictional planning requests and choices go to Google. Free Tier may use submitted content and responses for product improvement and human review. Only the common destination-time window is sent; your individual city, ceiling, travel legs and private answer text are not sent. Do not enter personal information in shareable test choices.</p></>}
 <label className="check"><input type="checkbox" checked={ack} onChange={e=>setAck(e.target.checked)}/>I checked my personal summary and agree to share the interests, places and reviewed planning requests listed above with this trip.</label><Button disabled={!ack||!requestsReviewed||editingDate} onClick={()=>void confirm()}>{busy?'Saving…':'Confirm my private summary'}</Button></fieldset>}
 {saved?.confirmed&&<Note title="Your personal summary is confirmed" tone="mint">You can edit it below. Reopening input pauses the shared plan and requires a new generation and fresh review.</Note>}
 </>}
 {!saved?.confirmed&&!['archived','postponed'].includes(state.stage)&&<Actions>{step>0&&<Button disabled={busy||editingDate} variant="secondary" onClick={()=>{setStep(x=>x-1);setError('');}}>Back</Button>}{step<5&&<Button disabled={busy||editingDate} onClick={next}>Continue</Button>}{step===5&&<Button variant="secondary" disabled={busy} onClick={()=>setStep(0)}>Edit my answers</Button>}</Actions>}
 {saved?.confirmed&&!['archived','postponed'].includes(state.stage)&&<details><summary>Edit my confirmed answers</summary><label className="check"><input type="checkbox" checked={reopenAck} onChange={e=>setReopenAck(e.target.checked)}/>I understand that editing requires fresh planning and group review.</label><Button disabled={busy||!reopenAck} variant="secondary" onClick={async()=>{try{await onAct('reopen_input',{expected_input_revision:saved.revision,acknowledged:true});setStep(0);setReopenAck(false);}catch(e){setError(readableError(e));}}}>Reopen my private input</Button></details>}
 </Card><aside><Card title="A plan everyone can join" tone="mint"><p>{state.confirmed} of {state.included} included travellers have confirmed.</p><p>The shared itinerary waits for everyone. Your private answers stay with you; the group sees your completion status.</p><p>The plan will show the outcome of each shared request. Review exclusions and unverified conditions before you agree. Your private reasons stay with you.</p><Button variant="secondary" onClick={onDone}>Back to trip overview</Button></Card></aside></div>;
}

function PlanningRequestsEditor({value,onChange}:{value:PlanningRequest[];onChange:(v:PlanningRequest[])=>void}){
 const update=(index:number,patch:Partial<PlanningRequest>)=>onChange(value.map((r,i)=>i===index?{...r,...patch}:r));
 return <div className="stack">{value.map((r,i)=><div className="flow-poll" key={i}><Field label={'Planning request '+(i+1)}><input value={r.title} maxLength={120} onChange={e=>update(i,{title:e.target.value})}/></Field><div className="field-grid"><Field label={'Type for request '+(i+1)}><select value={r.kind} onChange={e=>update(i,{kind:e.target.value as PlanningRequest['kind']})}><option value="activity">Activity or place</option><option value="food">Meal requirement</option><option value="stay">Stay requirement</option><option value="rule">Other condition to verify</option></select></Field><Field label={'Priority for request '+(i+1)}><select value={r.priority} onChange={e=>update(i,{priority:e.target.value as PlanningRequest['priority']})}><option value="hard">Must-have · consider first</option><option value="soft">Flexible preference</option></select></Field></div><Button variant="ghost" onClick={()=>onChange(value.filter((_,n)=>i!==n))}>Remove request {i+1}</Button></div>)}<Button variant="secondary" disabled={value.length>=20} onClick={()=>onChange([...value,{title:'',kind:'activity',priority:'hard'}])}>Add a planning request</Button></div>;
}

import {useEffect,useRef,useState} from 'react';
import {readableError} from './backend';
import type {Workspace} from './backend';
import {flowApi,generateFlow} from './flowBackend';
import type {FlowState,FlowPoll} from './flowBackend';
import {PrivateConversation} from './PrivateConversation';
import {Button,Card,Actions,Badge,Field,Note} from './ui';
import {DateTimeField} from './DateTimeField';
import {flowMoney,flowStamp,localDate,requirementReason} from './privatePlanning';
import type {FlowDocument,FlowRef,FlowStep} from './privatePlanning';
export function LivePrivatePlanning({workspace:w,userId,tab,onRefresh,go}:{workspace:Workspace;userId:string;tab:string;onRefresh:()=>Promise<unknown>;go:(tab:string)=>void}){
 const [state,setState]=useState<FlowState|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[reviewAck,setReviewAck]=useState(false),[lockAck,setLockAck]=useState(false);
 const [deadline,setDeadline]=useState(localDate(w.trip.response_deadline)),[dateEditing,setDateEditing]=useState(false),[deadlineAck,setDeadlineAck]=useState(false);
 const mounted=useRef(true),inflight=useRef(false),readSequence=useRef(0),request=useRef<{signature:string;id:string}|null>(null);
 const organiser=w.members.some(m=>m.id===userId&&m.role==='organiser'),included=w.members.some(m=>m.id===userId&&m.included);
 async function load(){const sequence=++readSequence.current;const s=await flowApi('get',{trip_id:w.trip.id});if(mounted.current&&sequence===readSequence.current)setState(s);}
 useEffect(()=>{setReviewAck(false);setLockAck(false);},[state?.plan?.id,state?.stamp]);
 useEffect(()=>{mounted.current=true;void load().catch(e=>mounted.current&&setError(readableError(e)));const focus=()=>{if(document.visibilityState==='visible'&&!inflight.current)void load().catch(e=>mounted.current&&setError(readableError(e)));};const timer=window.setInterval(focus,15000);window.addEventListener('focus',focus);return()=>{mounted.current=false;clearInterval(timer);window.removeEventListener('focus',focus);};},[w.trip.id,userId]);
 useEffect(()=>{if(state&&w.trip.revision!==state.revision&&!inflight.current)void load().catch(e=>mounted.current&&setError(readableError(e)));},[w.trip.revision]);
 async function act(action:string,payload:Record<string,unknown>={}){
  if(!state||inflight.current)throw Error('Wait for the current action to finish.');
  inflight.current=true;readSequence.current++;setBusy(true);setError('');setNotice('');
  const body={trip_id:w.trip.id,expected_revision:state.revision,expected_stamp:state.stamp,...payload},signature=JSON.stringify([action,body]);
  if(request.current?.signature!==signature)request.current={signature,id:crypto.randomUUID()};
  try{const result=await flowApi(action,{...body,request_id:request.current.id});request.current=null;if(mounted.current){setState(result);setReviewAck(false);setLockAck(false);setNotice(action==='lock'?'The resolved itinerary is locked. No reservation was made.':action==='confirm_input'?'Your private summary is confirmed and saved.':'Saved. Showing the current planning state.');}await onRefresh();}
  catch(e){if(mounted.current)setError(readableError(e));throw e;}finally{inflight.current=false;if(mounted.current)setBusy(false);}
 }
 const doAct=(action:string,payload:Record<string,unknown>={})=>{void act(action,payload).catch(()=>{});};
 async function generate(){if(!state||inflight.current)return;inflight.current=true;readSequence.current++;setBusy(true);setError('');setNotice('');
  try{const result=await generateFlow({trip_id:w.trip.id,expected_revision:state.revision,expected_stamp:state.stamp,request_id:crypto.randomUUID()});if(mounted.current){setState(result);setReviewAck(false);setLockAck(false);setNotice('A fictional itinerary is ready for step decisions and your personal review.');}await onRefresh();}
  catch(e){if(mounted.current)setError(readableError(e));}finally{inflight.current=false;if(mounted.current)setBusy(false);}
 }
 if(!state)return <Card title="Opening the planning flow…">{error?<><p role="alert">{error}</p><Button onClick={()=>void load().catch(e=>setError(readableError(e)))}>Retry</Button></>:<p>Checking your trip and private summary.</p>}</Card>;
 const s=state,p=s.plan,frozen=['archived','postponed'].includes(s.stage),refs=s.context?.refs||[];
 const unresolved=s.polls.filter(p=>['open','unresolved'].includes(p.status)),readyToReview=Boolean(p&&!p.locked&&!frozen&&!unresolved.length&&!s.personal_checks_pending&&!p.document.unplaced.length&&!p.requirements_legacy);
 const name=(id:string)=>({rest:'Free time / rest',food:'Current meal arrangement',food_alternative:'Alternative meal arrangement',stay:'Current stay arrangement',stay_alternative:'Alternative stay arrangement',rest_alternative:'Alternative rest arrangement'}[id]||refs.find(r=>r.id===id)?.title||id);
 return <div className="stack planning-v2">
 {error&&<p className="form-error" role="alert">{error} Your saved input is kept. <Button variant="ghost" disabled={busy} onClick={()=>void load().catch(e=>setError(readableError(e)))}>Refresh planning</Button></p>}{notice&&<p className="notice" role="status">{notice}</p>}
 {tab==='preferences'?<PrivateConversation key={w.trip.id+userId+':'+(s.own?.revision||0)+':'+Boolean(s.own?.confirmed)} workspace={w} state={s} busy={busy} onAct={act} onDone={()=>go('')}/>:
 tab==='history'?<FlowVersionHistory state={s} tripId={w.trip.id}/>:
 tab==='bookings'?<Card title={p?.locked?'Itinerary locked — booking guidance comes next':'Lock the resolved itinerary first'}><p>{p?.locked?'Your agreed planning baseline is saved. Live travel providers and the new booking-guidance flow are the next package. No reservation or payment has been made.':'Complete the step decisions and each person’s review before organiser lock-in.'}</p><Button onClick={()=>go('plan')}>View the itinerary</Button></Card>:
 <>
 <div className="journey-progress" aria-label="Planning journey">{[['1','Private inputs',s.confirmed===s.included],['2','Shared itinerary',Boolean(p)],['3','Step decisions',Boolean(p)&&!unresolved.length],['4','Personal review',Boolean(p)&&p!.review_count===s.included],['5','Locked',Boolean(p?.locked)]].map(([i,label,done])=><span key={String(i)} className={done?'complete':''}>{done?'✓':i} · {label}</span>)}</div>
 {!p?<Card title="Everyone’s input comes first" tone="mint"><h3>{s.confirmed} of {s.included} included travellers confirmed</h3><p>{s.blocker||'The private summaries are complete. The organiser can now generate the group itinerary.'}</p><p>The shared plan uses the time everyone has in common. Each person keeps their own arrival, return and travel allowance.</p><Actions><Button onClick={()=>go('preferences')}>{s.own?.confirmed?'Review my private summary':'Add my private input'}</Button>{organiser&&<Button disabled={busy||frozen||Boolean(s.blocker)||!s.ai_available} onClick={()=>void generate()}>{busy?'Planning…':'Generate fictional itinerary with Gemini'}</Button>}</Actions>{!s.blocker&&!s.ai_available&&<p className="caption">Gemini Free Tier requires a trip labelled TEST · AI and separate fictional-input/AI consent from every included person. Real private inputs remain manual.</p>}
 {organiser&&!frozen&&<details><summary>Extend the response deadline</summary><DateTimeField label="New response deadline" value={deadline} onChange={setDeadline} onEditingChange={setDateEditing}/><label className="check"><input type="checkbox" checked={deadlineAck} onChange={e=>setDeadlineAck(e.target.checked)}/>A new deadline requires fresh planning and review.</label><Button disabled={busy||dateEditing||!deadlineAck} onClick={()=>doAct('extend_deadline',{deadline:deadline+':00+05:30',acknowledged:true})}>Apply new deadline</Button></details>}
 </Card>:<>
 {p.requirements_legacy&&!p.locked&&<Note title="This earlier draft did not evaluate all requirements" tone="cream">Your saved answers are unchanged. Open your private summary, reopen it, review the planning requests to share, then confirm and generate a fresh draft.<Button variant="secondary" onClick={()=>go('preferences')}>Review my private summary</Button></Note>}
 {Boolean(p.own_requirement_checks?.length)&&<Card title="What happened to my requirements" sub="Only you see which requests belong to you. Exclusions need your review before agreement.">{p.own_requirement_checks!.map((r,i)=><section className="flow-poll" key={i}><Badge tone={r.status==='included'?'positive':'pending'}>{r.status==='included'?'Included in draft':'Excluded'}</Badge><h3>{r.title}</h3><p>{r.priority==='hard'?'Must-have':'Flexible preference'} · {requirementReason(r.reason)}</p>{r.steps.length>0&&<p className="caption">{r.steps.map(x=>x.replace('step_','Step ')).join(' · ')}</p>}</section>)}</Card>}
 {s.own&&<Card title="My complete journey" sub="Your private travel legs surround the shared time at the destination."><ol className="personal-journey"><li><strong>Depart from {s.own.content.origin}</strong><span>{flowStamp(s.own.content.start)} IST</span></li><li><strong>Destination arrival allowance</strong><span>{flowStamp(new Date(Date.parse(s.own.content.start)+s.own.content.outbound_minutes*60000).toISOString())} IST</span></li><li><strong>Shared itinerary</strong><span>{flowStamp(p.document.start)} → {flowStamp(p.document.end)} IST</span></li><li><strong>Begin my return journey</strong><span>{flowStamp(new Date(Date.parse(s.own.content.end)-s.own.content.return_minutes*60000).toISOString())} IST</span></li><li><strong>Return by</strong><span>{flowStamp(s.own.content.end)} IST</span></li></ol><p className="caption">The personal allowance covers return travel and time outside the shared itinerary. Durations are your estimates, not verified transport schedules.</p></Card>}
 <Card title={p.locked?'Your locked itinerary':'Your shared itinerary'} sub={'Version '+p.version+' · '+flowStamp(p.document.start)+' → '+flowStamp(p.document.end)+' IST'}><Badge tone={p.locked?'positive':'pending'}>{p.locked?'Locked planning baseline':'Draft for your group'}</Badge><p className="small">Fictional reference estimates: food ₹350 per meal block, activities/local travel use stated fictional allowances (surfing ₹2,500, scuba ₹4,500, sailing ₹2,000; other activities ₹550 each), stay ₹1,500 per night, ₹50 fees and 10% contingency. Accommodation, food and activities are suggestions; availability and live prices are unverified.</p>{p.document.unplaced.length>0&&<Note title="Some shared choices do not fit" tone="cream">{p.document.unplaced.map(name).join(' · ')}. Resolve the competing choices through step voting, or revise your shareable choices and generate again.</Note>}<FlowTimeline document={p.document} refs={refs} polls={s.polls} editable={!busy&&!frozen&&!p.locked&&included} concern={(id,replacement,hard)=>act('raise_concern',{step_id:id,replacement,hard})} openVote={()=>go('voting')}/></Card>
 {tab==='voting'&&<Card title="Resolve one step at a time" sub="Choose between shared alternatives. Missing replies never count as approval.">{s.polls.length?s.polls.map(poll=><FlowPollView key={poll.id} poll={poll} planId={p.id} total={s.included} name={name} busy={busy||frozen||p.locked||!included} act={act}/>):<p>No step votes are open. Raise a concern on a step if the plan needs a change.</p>}</Card>}
 {tab!=='voting'&&unresolved.length>0&&<Note title={unresolved.length+' step decisions need your group'} tone="cream"><Button onClick={()=>go('voting')}>Open step voting</Button></Note>}
 <div className="columns"><Card title="Your private whole-trip check"><dl className="personal-summary"><dt>Shared itinerary estimate</dt><dd>{flowMoney(p.document.cost_paise)}</dd><dt>Your return travel and extra-time allowance</dt><dd>{flowMoney(s.own?.content.travel_reserve_paise||0)}</dd><dt>Your complete estimated total</dt><dd>{flowMoney(p.own_total_paise)}</dd><dt>Your private ceiling</dt><dd>{flowMoney(s.own?.content.ceiling_paise||0)}</dd></dl>{s.own&&<details><summary>Check my personal availability and requirements</summary><p>{flowStamp(s.own.content.start)} → {flowStamp(s.own.content.end)} IST</p><p className="preserve-lines">Must-haves: {s.own.content.hard}</p><p className="preserve-lines">Flexible: {s.own.content.soft}</p></details>}
 {p.own_over_budget&&<p className="form-error">This estimate exceeds your private ceiling. Revise your input; a vote cannot override it.</p>}
 {s.personal_checks_pending&&<p className="caption">A personal requirement still needs its author’s review. Its private reason is not shared.</p>}
 {!p.locked&&<><label className="check"><input type="checkbox" disabled={!readyToReview||busy||p.own_over_budget||!included} checked={reviewAck} onChange={e=>setReviewAck(e.target.checked)}/>I checked this exact itinerary, my personal arrival/return arrangements and complete estimate. I have read the included and excluded requests above, accept the disclosed exclusions for this version, and checked any unverified conditions. These are fictional estimates, not verified booking prices.</label><Button disabled={!readyToReview||busy||!reviewAck||p.own_over_budget||!included} onClick={()=>doAct('review',{plan_id:p.id,acknowledged:true,accept_exclusions:reviewAck})}>{p.reviewed?'Reconfirm my review':'Confirm my personal review'}</Button></>}
 </Card><Card title="Lock the resolved itinerary" tone="mint"><p>{p.review_count} of {s.included} included travellers reviewed this version.</p><p>Any itinerary change requires a fresh personal review. Availability and ceilings remain limits. Excluded requests are disclosed, and each affected traveller must accept this exact version.</p>{organiser&&!p.locked&&<><label className="check"><input type="checkbox" checked={lockAck} disabled={busy||!readyToReview||p.review_count!==s.included} onChange={e=>setLockAck(e.target.checked)}/>Lock this resolved version as our planning baseline.</label><Button disabled={busy||!readyToReview||p.review_count!==s.included||!lockAck} onClick={()=>doAct('lock',{plan_id:p.id,acknowledged:true})}>Lock resolved itinerary</Button><details><summary>Generate another draft</summary><p>Earlier versions remain in History. A new draft needs fresh votes and personal reviews.</p><Button variant="secondary" disabled={busy||frozen||!s.ai_available} onClick={()=>void generate()}>Generate another fictional draft</Button></details></>}{p.locked&&<><p>No reservation or purchase has been made.</p><Button onClick={()=>go('bookings')}>Next: booking guidance</Button></>}{!organiser&&!p.locked&&<p>The organiser locks the itinerary after everyone reviews.</p>}</Card></div>
 </>}
 </>}
 </div>;
}
function FlowTimeline({document:d,refs,polls,editable,concern,openVote}:{document:FlowDocument;refs:FlowRef[];polls:FlowPoll[];editable:boolean;concern:(step:string,replacement:string,hard:boolean)=>Promise<void>;openVote:()=>void}){
 const days=new Map<string,FlowStep[]>();for(const s of d.steps){const day=localDate(s.start).slice(0,10);days.set(day,[...(days.get(day)||[]),s]);}
 return <div className="flow-days">{[...days].map(([day,steps],index)=><details key={day} open={index===0||days.size<=3}><summary>Day {index+1} · {new Date(day+'T12:00:00+05:30').toLocaleDateString('en-IN',{dateStyle:'long'})}</summary><ol className="itinerary-timeline">{steps.map(step=><li key={step.id}><div className="actions"><Badge>{step.kind}</Badge><strong>{step.kind==='activity'?(refs.find(r=>r.id===step.ref)?.title||'Free time / rest'):step.kind==='food'?'Meal break and local arrangements':step.kind==='stay'?'Stay / overnight rest':'Free time / rest'}{step.ref.endsWith('_alternative')?' · revised arrangement':''}</strong></div><p>{flowStamp(step.start)} → {flowStamp(step.end)} IST</p>{d.requirements_version===1&&refs.filter(r=>r.kind===step.kind&&step.kind!=='activity').map(r=><p className="caption" key={r.id}>Requested: {r.title} · verify availability at booking</p>)}<p className="caption">{flowMoney(step.cost_paise)} per person · fictional allowance</p>{polls.some(p=>p.step_id===step.id&&['open','unresolved'].includes(p.status))?<Button variant="secondary" onClick={openVote}>View this step’s vote</Button>:editable?<StepConcern step={step} refs={refs} save={(ref,hard)=>concern(step.id,ref,hard)}/>:null}</li>)}</ol></details>)}</div>;
}
function StepConcern({step,refs,save}:{step:FlowStep;refs:FlowRef[];save:(ref:string,hard:boolean)=>Promise<void>}){
 const options=step.kind==='activity'?[{id:'rest',title:'Free time / rest'},...refs.filter(r=>!r.kind||r.kind==='activity')]:[{id:step.kind,title:'Original arrangement'},{id:step.kind+'_alternative',title:'Alternative '+step.kind+' arrangement (verify my needs)'}];
