 const [choice,setChoice]=useState(p.own_ballot?.choice||''),[ack,setAck]=useState(false);useEffect(()=>setChoice(p.own_ballot?.choice||''),[p.own_ballot?.revision]);useEffect(()=>setAck(false),[planId]);
