 {p.status==='open'&&<fieldset className="auth-fields" disabled={busy||Date.parse(p.deadline)<=Date.now()}><Field label={'My ballot for '+p.step_id}><select value={choice} onChange={e=>setChoice(e.target.value)}><option value="">Choose a response</option>{p.options.map((o,i)=><option key={o} value={o}>{p.mode==='concern'?(i===0?'Reject change · ':'Accept change · '):''}{name(o)}</option>)}<option value="abstain">Abstain</option></select></Field><Button disabled={!choice} onClick={()=>submit('vote',{poll_id:p.id,choice,expected_ballot_revision:p.own_ballot?.revision||0})}>Save my step ballot</Button></fieldset>}
 {['open','unresolved'].includes(p.status)&&<Button variant="secondary" disabled={busy||(p.responded<total&&Date.parse(p.deadline)>Date.now())} onClick={()=>submit('close_poll',{poll_id:p.id})}>Close and resolve step vote</Button>}
 {p.result&&<p>{Object.entries(p.result.counts).map(([k,n])=>name(k)+': '+n).join(' · ')} · Abstain: {p.result.abstain} · Missing: {p.result.missing}. {p.result.winner?'Saved: '+name(p.result.winner):'No winner. Review the private inputs and generate a revised plan.'}</p>}
 {p.own_requirement&&!p.personal_resolved&&['closed','stale'].includes(p.status)&&<><label className="check"><input type="checkbox" checked={ack} disabled={busy} onChange={e=>setAck(e.target.checked)}/>I checked the current resulting itinerary; I accept the current outcome of my requirement, including any disclosed exclusion.</label><Button disabled={busy||!ack} onClick={()=>submit('resolve_personal',{poll_id:p.id,plan_id:planId,acknowledged:true})}>Resolve my personal requirement</Button></>}
 </section>;
