test('Fictional consent cannot be attached to real answers',()=>assert.throws(()=>validatePersonal({...input,fictional:false},[win])));
test('Shared reference output rejects invented, duplicate or omitted choices',()=>{for(const change of [{sequence:['ref_1']},{sequence:['ref_1','ref_1']},{sequence:['ref_1','not_allowed']},{conflicts:[{a:'ref_1',b:'not_allowed'}]}])assert.throws(()=>validateFlowChoice({...choice,...change},refs));});
test('Generated output cannot carry arbitrary private prose or hidden fields',()=>assert.throws(()=>validateFlowChoice({...choice,private_reason:'CANARY'},refs)));
test('Shared timeline is continuous and bounded to every person’s common interval',()=>{const doc=buildFlowDocument(context,choice);assert.equal(Date.parse(doc.steps[0].start),Date.parse(context.start));for(let i=1;i<doc.steps.length;i++)assert.equal(doc.steps[i].start,doc.steps[i-1].end);assert.equal(Date.parse(doc.steps.at(-1).end),Date.parse(context.end));});
test('Overnight blocks merge across midnight and retain a single stay allowance',()=>{const doc=buildFlowDocument({...context,start:'2026-11-13T21:00:00+05:30',end:'2026-11-14T06:00:00+05:30'},choice);assert.equal(doc.steps.length,1);assert.equal(doc.steps[0].cost_paise,150000);assert.equal(doc.cost_paise,170500);assert.equal(doc.unplaced.length,2);});
test('The estimate includes every shared step, fees and exact integer contingency',()=>{const doc=buildFlowDocument(context,choice);assert.equal(doc.cost_paise,(doc.steps.reduce((n,x)=>n+x.cost_paise,0)+5000)*11/10);assert(Number.isInteger(doc.cost_paise));});
test('Unscheduled shareable requests remain explicit instead of being silently dropped',()=>{const doc=buildFlowDocument({...context,start:'2026-11-13T09:00:00+05:30',end:'2026-11-13T12:00:00+05:30'},choice);assert.deepEqual(doc.unplaced,['ref_2']);});
test('A short activity interval becomes rest and no activity is falsely counted as covered',()=>{const doc=buildFlowDocument({...context,start:'2026-11-13T11:30:00+05:30',end:'2026-11-13T12:30:00+05:30'},choice);assert.equal(doc.steps[0].kind,'rest');assert.equal(doc.unplaced.length,2);});
