test('Surfing and scuba are separate hard requests; sailing remains flexible',()=>{const r=suggestPlanningRequests('TEST FICTIONAL: Non-vegetarian meals must be available; I want to do surfing and scuba diving.','TEST FICTIONAL: Prefer a relaxed beach day; prefer sailing, activities can move.');assert.deepEqual(r.filter(x=>x.priority==='hard'&&x.kind==='activity').map(x=>x.title.toLowerCase()),['surfing','scuba diving']);assert(r.some(x=>x.priority==='soft'&&/sailing/i.test(x.title)));assert(r.some(x=>x.kind==='food'));});
